/* Native MediaLibrary owner.
 *
 * Kodi and Jellyfin are interaction grammars, not identities or databases to
 * copy.  This owner records only library bindings, viewer access and local
 * playback continuity.  CMS MediaProgram remains the representation owner;
 * a prepared playback plan never proves a byte was delivered or watched. */
#define _POSIX_C_SOURCE 200809L
#include <sqlite3.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/wait.h>
#include <time.h>
#include <unistd.h>

static const char *arg(int ac,char **av,const char *name){for(int i=2;i+1<ac;i++)if(!strcmp(av[i],name))return av[i+1];return NULL;}
static int has(int ac,char **av,const char *name){for(int i=2;i<ac;i++)if(!strcmp(av[i],name))return 1;return 0;}
static void js(const char*s){const unsigned char*p=(const unsigned char*)(s?s:"");putchar('"');for(;*p;p++){if(*p=='"'||*p=='\\'){putchar('\\');putchar(*p);}else if(*p=='\n')fputs("\\n",stdout);else if(*p=='\r')fputs("\\r",stdout);else if(*p=='\t')fputs("\\t",stdout);else if(*p<32)printf("\\u%04x",*p);else putchar(*p);}putchar('"');}
static int sql(sqlite3*d,const char*s){char*e=0;int ok=sqlite3_exec(d,s,0,0,&e)==SQLITE_OK;if(!ok){fprintf(stderr,"sqlite: %s\n",e?e:"error");sqlite3_free(e);}return ok;}
static int token(const char*s){if(!s||!*s||strlen(s)>180)return 0;for(;*s;s++)if(!((*s>='a'&&*s<='z')||(*s>='A'&&*s<='Z')||(*s>='0'&&*s<='9')||*s==':'||*s=='-'||*s=='_'||*s=='.'))return 0;return 1;}

/* Public catalog/playback ingress obtains its caller coordinate from the
 * native Auth owner.  The supplied auth DB/token are passed only to that
 * owner; MediaLibrary consumes a short-lived ActorClosure projection and
 * never reads Auth tables or treats a user/session as an Actor identity. */
static int json_string_field(const char *json,const char *key,char *out,size_t cap){char needle[128];const char *p;size_t n=0;if(!json||!key||!out||cap<2||snprintf(needle,sizeof(needle),"\"%s\"",key)>=(int)sizeof(needle))return 0;p=strstr(json,needle);if(!p||(p=strchr(p+strlen(needle),':'))==0)return 0;while(*++p==' '||*p=='\t'||*p=='\r'||*p=='\n'){}if(*p++!='\"')return 0;while(*p&&*p!='\"'){if(*p=='\\'){if(!*++p)return 0;}if((unsigned char)*p<32||n+1>=cap)return 0;out[n++]=*p++;}if(*p!='\"'||!n)return 0;out[n]='\0';return 1;}
static int json_true_field(const char *json,const char *key){char needle[128];const char *p;if(!json||!key||snprintf(needle,sizeof(needle),"\"%s\"",key)>=(int)sizeof(needle))return 0;p=strstr(json,needle);if(!p||(p=strchr(p+strlen(needle),':'))==0)return 0;while(*++p==' '||*p=='\t'||*p=='\r'||*p=='\n'){}return !strncmp(p,"true",4) && (p[4]=='}'||p[4]==','||p[4]==' '||p[4]=='\n'||p[4]=='\r');}
static int stdin_token(char *out,size_t cap){size_t n=0;int ch;if(!out||cap<2)return 0;while((ch=fgetc(stdin))!=EOF){if(ch=='\n'||ch=='\r')break;if(ch<0x21||ch>0x7e||n+1>=cap)return 0;out[n++]=(char)ch;}out[n]='\0';return n>0;}
static int auth_actor_closure(int ac,char**av,char *actor,size_t actor_cap){const char *auth_db=arg(ac,av,"--auth-db"),*auth_token=arg(ac,av,"--auth-token"),*configured=getenv("BONFYRE_AUTH_BIN"),*auth_bin=configured&&*configured?configured:"bonfyre-auth";const char *expected=arg(ac,av,"--actor");char stdin_auth_token[192];int input[2]={-1,-1},output[2]={-1,-1},status=0;pid_t child;char buf[4096];ssize_t got,n;if(!auth_token&&has(ac,av,"--auth-token-stdin")){if(!stdin_token(stdin_auth_token,sizeof(stdin_auth_token)))return 0;auth_token=stdin_auth_token;}if(!auth_db||!auth_token||!token(auth_token)||(expected&&!token(expected))||pipe(input)!=0||pipe(output)!=0){if(input[0]>=0){close(input[0]);close(input[1]);}if(output[0]>=0){close(output[0]);close(output[1]);}return 0;}child=fork();if(child<0){close(input[0]);close(input[1]);close(output[0]);close(output[1]);return 0;}if(child==0){char *const args[]={ (char*)auth_bin,"--db",(char*)auth_db,"actor-closure-stdin",0};close(input[1]);close(output[0]);if(dup2(input[0],STDIN_FILENO)<0||dup2(output[1],STDOUT_FILENO)<0)_exit(127);close(input[0]);close(output[1]);execvp(auth_bin,args);_exit(127);}close(input[0]);close(output[1]);if(write(input[1],auth_token,strlen(auth_token))!=(ssize_t)strlen(auth_token)||write(input[1],"\n",1)!=1){close(input[1]);close(output[0]);waitpid(child,&status,0);return 0;}close(input[1]);got=0;while(got<(ssize_t)sizeof(buf)-1&&(n=read(output[0],buf+got,sizeof(buf)-1-(size_t)got))>0)got+=n;close(output[0]);if(waitpid(child,&status,0)<0||!WIFEXITED(status)||WEXITSTATUS(status)!=0||got<=0)return 0;buf[got]='\0';if(!json_true_field(buf,"authenticated")||!json_string_field(buf,"actor_subject",actor,actor_cap)||!token(actor))return 0;if(expected&&strcmp(expected,actor))return 0;return 1;}
typedef int (*actor_handler)(sqlite3*,int,char**);
static int authenticated_call(sqlite3*d,int ac,char**av,actor_handler handler){char actor[256];char *copy[128];int n=0;if(!auth_actor_closure(ac,av,actor,sizeof(actor))||ac+2>(int)(sizeof(copy)/sizeof(*copy)))return 0;for(int i=0;i<ac;i++)copy[n++]=av[i];copy[n++]="--actor";copy[n++]=actor;return handler(d,n,copy);}
/* Address terms deliberately carry coarse forwarding coordinates, not raw
 * owner identifiers.  Canonical subject/program identities remain references
 * in the descriptor; this conversion merely produces the CUE address atom. */
static int term_atom(const char *in, char *out, size_t cap) {
    size_t n = 0; int dash = 0;
    if (!in || !*in || cap < 2) return 0;
    for (; *in; ++in) {
        unsigned char c = (unsigned char)*in;
        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')) {
            if (n + 1 >= cap) return 0;
            out[n++] = (char)((c >= 'A' && c <= 'Z') ? c + ('a' - 'A') : c);
            dash = 0;
        } else if (!dash && n) {
            if (n + 1 >= cap) return 0;
            out[n++] = '-'; dash = 1;
        }
    }
    while (n && out[n - 1] == '-') --n;
    out[n] = '\0';
    return n != 0;
}
static int safe_asset(const char*s){return s&&s[0]=='/'&&s[1]!='/'&&!strstr(s,"..")&&!strchr(s,'\\');}
static int schema(sqlite3*d){return sql(d,
 "PRAGMA journal_mode=WAL;"
 "CREATE TABLE IF NOT EXISTS media_library(library_id TEXT PRIMARY KEY,mode TEXT NOT NULL CHECK(mode IN('personal','community')),owner_subject TEXT NOT NULL,title TEXT NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN('private','community','public')),state TEXT NOT NULL CHECK(state IN('active','retired')),updated_at INTEGER NOT NULL);"
 "CREATE TABLE IF NOT EXISTS media_library_access(library_id TEXT NOT NULL REFERENCES media_library(library_id) ON DELETE CASCADE,actor_subject TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('viewer','curator','admin')),state TEXT NOT NULL CHECK(state IN('active','revoked')),updated_at INTEGER NOT NULL,PRIMARY KEY(library_id,actor_subject));"
 "CREATE TABLE IF NOT EXISTS media_library_membership(library_id TEXT NOT NULL REFERENCES media_library(library_id) ON DELETE CASCADE,subject_ref TEXT NOT NULL,media_program_ref TEXT NOT NULL,collection_ref TEXT NOT NULL DEFAULT '',state TEXT NOT NULL CHECK(state IN('active','removed')),added_at INTEGER NOT NULL,PRIMARY KEY(library_id,subject_ref,media_program_ref));"
 "CREATE TABLE IF NOT EXISTS media_playback_session(session_id TEXT PRIMARY KEY,library_id TEXT NOT NULL,actor_subject TEXT NOT NULL,subject_ref TEXT NOT NULL,media_program_ref TEXT NOT NULL,representation_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('prepared','playing','paused','ended')),position_ms INTEGER NOT NULL CHECK(position_ms>=0),opened_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);"
 "CREATE INDEX IF NOT EXISTS media_continue_by_actor ON media_playback_session(actor_subject,library_id,updated_at DESC);");}
static int open_db(const char*p,sqlite3**out){if(!p||sqlite3_open_v2(p,out,SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE,0)!=SQLITE_OK)return 0;sqlite3_busy_timeout(*out,5000);if(!schema(*out)){sqlite3_close(*out);*out=0;return 0;}return 1;}
static int owner_or_role(sqlite3*d,const char*lib,const char*actor,int manage){sqlite3_stmt*s=0;int ok=0;if(!d||!lib||!actor)return 0;if(sqlite3_prepare_v2(d,"SELECT 1 FROM media_library WHERE library_id=?1 AND state='active' AND owner_subject=?2 UNION ALL SELECT 1 FROM media_library_access WHERE library_id=?1 AND actor_subject=?2 AND state='active' AND (?3=0 OR role IN ('curator','admin')) LIMIT 1",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,lib,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,actor,-1,SQLITE_TRANSIENT);sqlite3_bind_int(s,3,manage);ok=sqlite3_step(s)==SQLITE_ROW;sqlite3_finalize(s);return ok;}
static int visible(sqlite3*d,const char*lib,const char*actor){sqlite3_stmt*s=0;int ok=0;if(sqlite3_prepare_v2(d,"SELECT 1 FROM media_library WHERE library_id=?1 AND state='active' AND visibility='public' UNION ALL SELECT 1 FROM media_library WHERE library_id=?1 AND state='active' AND owner_subject=?2 UNION ALL SELECT 1 FROM media_library_access WHERE library_id=?1 AND actor_subject=?2 AND state='active' LIMIT 1",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,lib,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,actor?actor:"anonymous",-1,SQLITE_TRANSIENT);ok=sqlite3_step(s)==SQLITE_ROW;sqlite3_finalize(s);return ok;}
static int cmd_library(sqlite3*d,int ac,char**av){const char*id=arg(ac,av,"--id"),*mode=arg(ac,av,"--mode"),*owner=arg(ac,av,"--owner"),*title=arg(ac,av,"--title"),*visibility=arg(ac,av,"--visibility"),*actor=arg(ac,av,"--actor");sqlite3_stmt*s=0;int ok=0;if(!token(id)||!token(owner)||!token(actor)||!title||!mode||!visibility||((strcmp(mode,"personal")&&strcmp(mode,"community"))||(strcmp(visibility,"private")&&strcmp(visibility,"community")&&strcmp(visibility,"public"))))return 0;if(strcmp(actor,owner))return 0;if(sqlite3_prepare_v2(d,"INSERT INTO media_library VALUES(?1,?2,?3,?4,?5,'active',?6) ON CONFLICT(library_id) DO UPDATE SET mode=excluded.mode,title=excluded.title,visibility=excluded.visibility,updated_at=excluded.updated_at WHERE media_library.owner_subject=excluded.owner_subject",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,id,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,mode,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,owner,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,4,title,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,5,visibility,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,6,time(0));ok=sqlite3_step(s)==SQLITE_DONE&&sqlite3_changes(d)==1;sqlite3_finalize(s);if(ok){fputs("{\"schema\":\"bonfyre-media-library.v1\",\"library_id\":",stdout);js(id);fputs(",\"state\":\"active\",\"truth\":\"library_binding_owner_only\"}\n",stdout);}return ok;}
static int cmd_access(sqlite3*d,int ac,char**av){const char*lib=arg(ac,av,"--library"),*actor=arg(ac,av,"--actor"),*role=arg(ac,av,"--role"),*state=arg(ac,av,"--state"),*by=arg(ac,av,"--by");sqlite3_stmt*s=0;int ok=0;if(!token(lib)||!token(actor)||!token(by)||!role||!state||!owner_or_role(d,lib,by,1)||((strcmp(role,"viewer")&&strcmp(role,"curator")&&strcmp(role,"admin"))||(strcmp(state,"active")&&strcmp(state,"revoked"))))return 0;if(sqlite3_prepare_v2(d,"INSERT INTO media_library_access VALUES(?1,?2,?3,?4,?5) ON CONFLICT(library_id,actor_subject) DO UPDATE SET role=excluded.role,state=excluded.state,updated_at=excluded.updated_at",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,lib,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,actor,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,role,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,4,state,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,5,time(0));ok=sqlite3_step(s)==SQLITE_DONE;sqlite3_finalize(s);if(ok){fputs("{\"schema\":\"bonfyre-media-library-access.v1\",\"library_id\":",stdout);js(lib);fputs(",\"actor_subject\":",stdout);js(actor);fputs(",\"state\":",stdout);js(state);fputs(",\"truth\":\"library_access_owner_only\"}\n",stdout);}return ok;}
static int cmd_bind(sqlite3*d,int ac,char**av){const char*lib=arg(ac,av,"--library"),*subject=arg(ac,av,"--subject"),*program=arg(ac,av,"--program"),*collection=arg(ac,av,"--collection"),*state=arg(ac,av,"--state"),*by=arg(ac,av,"--by");sqlite3_stmt*s=0;int ok=0;if(!token(lib)||!token(subject)||!token(program)||!token(by)||!owner_or_role(d,lib,by,1)||!state||((strcmp(state,"active")&&strcmp(state,"removed"))))return 0;if(!collection)collection="";if(sqlite3_prepare_v2(d,"INSERT INTO media_library_membership VALUES(?1,?2,?3,?4,?5,?6) ON CONFLICT(library_id,subject_ref,media_program_ref) DO UPDATE SET collection_ref=excluded.collection_ref,state=excluded.state,added_at=excluded.added_at",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,lib,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,subject,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,program,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,4,collection,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,5,state,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,6,time(0));ok=sqlite3_step(s)==SQLITE_DONE;sqlite3_finalize(s);if(ok){fputs("{\"schema\":\"bonfyre-media-library-membership.v1\",\"library_id\":",stdout);js(lib);fputs(",\"subject_ref\":",stdout);js(subject);fputs(",\"state\":\"bound\",\"truth\":\"membership_not_media_identity_or_playback\"}\n",stdout);}return ok;}
static int has_col(sqlite3*d,const char*table,const char*name){sqlite3_stmt*s=0;int ok=0;char q[128];snprintf(q,sizeof(q),"PRAGMA table_info(%s)",table);if(sqlite3_prepare_v2(d,q,-1,&s,0)!=SQLITE_OK)return 0;while(sqlite3_step(s)==SQLITE_ROW){const char*v=(const char*)sqlite3_column_text(s,1);if(v&&!strcmp(v,name)){ok=1;break;}}sqlite3_finalize(s);return ok;}
typedef struct {char program[192],subject[256],kind[24],id[128],asset[1024],codec[64];int bitrate;int direct,found,needs_transcode;} Plan;
static int capability_codec(sqlite3*d,const char*cap,const char*codec,int bitrate){sqlite3_stmt*s=0;int ok=0,max=0;if(sqlite3_prepare_v2(d,"SELECT COALESCE(json_extract(?1,'$.max_bitrate_kbps'),0), EXISTS(SELECT 1 FROM json_each(?1,'$.codecs') WHERE value=?2 OR value='*') WHERE json_valid(?1)",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,cap,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,codec,-1,SQLITE_TRANSIENT);if(sqlite3_step(s)==SQLITE_ROW){max=sqlite3_column_int(s,0);ok=sqlite3_column_int(s,1)&&(!max||bitrate<=max);}sqlite3_finalize(s);return ok;}
static int resolve(sqlite3*d,const char*cms,const char*lib,const char*actor,const char*subject,const char*cap,Plan*p){sqlite3*cd=0;sqlite3_stmt*s=0,*reps=0;char raw[8192]={0};int best=-1;if(!visible(d,lib,actor)||!token(subject)||!cap||sqlite3_open_v2(cms,&cd,SQLITE_OPEN_READONLY,0)!=SQLITE_OK)return 0;if(sqlite3_prepare_v2(d,"SELECT media_program_ref FROM media_library_membership WHERE library_id=?1 AND subject_ref=?2 AND state='active' ORDER BY media_program_ref LIMIT 1",-1,&s,0)!=SQLITE_OK)goto out;sqlite3_bind_text(s,1,lib,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,subject,-1,SQLITE_TRANSIENT);if(sqlite3_step(s)!=SQLITE_ROW||!sqlite3_column_text(s,0))goto out;snprintf(p->program,sizeof(p->program),"%s",sqlite3_column_text(s,0));sqlite3_finalize(s);s=0;
 if(has_col(cd,"media_program","representations")){if(sqlite3_prepare_v2(cd,"SELECT subject_ref,media_kind,asset_ref,COALESCE(representations,'[]') FROM media_program WHERE program_id=?1 AND publication_state='published' AND status='published' ORDER BY id DESC LIMIT 1",-1,&s,0)!=SQLITE_OK)goto out;}else if(sqlite3_prepare_v2(cd,"SELECT subject_ref,media_kind,asset_ref,'[]' FROM media_program WHERE program_id=?1 AND publication_state='published' AND status='published' ORDER BY id DESC LIMIT 1",-1,&s,0)!=SQLITE_OK)goto out;
 sqlite3_bind_text(s,1,p->program,-1,SQLITE_TRANSIENT);if(sqlite3_step(s)!=SQLITE_ROW)goto out;snprintf(p->subject,sizeof(p->subject),"%s",sqlite3_column_text(s,0)?(const char*)sqlite3_column_text(s,0):"");snprintf(p->kind,sizeof(p->kind),"%s",sqlite3_column_text(s,1)?(const char*)sqlite3_column_text(s,1):"");snprintf(p->asset,sizeof(p->asset),"%s",sqlite3_column_text(s,2)?(const char*)sqlite3_column_text(s,2):"");snprintf(raw,sizeof(raw),"%s",sqlite3_column_text(s,3)?(const char*)sqlite3_column_text(s,3):"[]");sqlite3_finalize(s);s=0;if(strcmp(p->subject,subject)||!safe_asset(p->asset))goto out;
 if(sqlite3_prepare_v2(cd,"SELECT COALESCE(json_extract(value,'$.id'),'default'),COALESCE(json_extract(value,'$.asset_ref'),?2),COALESCE(json_extract(value,'$.codec'),'unknown'),COALESCE(json_extract(value,'$.bitrate_kbps'),0),COALESCE(json_extract(value,'$.delivery'),'direct') FROM json_each(?1) WHERE type='object'",-1,&reps,0)!=SQLITE_OK)goto out;sqlite3_bind_text(reps,1,raw,-1,SQLITE_TRANSIENT);sqlite3_bind_text(reps,2,p->asset,-1,SQLITE_TRANSIENT);
 while(sqlite3_step(reps)==SQLITE_ROW){const char*id=(const char*)sqlite3_column_text(reps,0),*asset=(const char*)sqlite3_column_text(reps,1),*codec=(const char*)sqlite3_column_text(reps,2),*delivery=(const char*)sqlite3_column_text(reps,4);int rate=sqlite3_column_int(reps,3);p->found=1;if(!asset||!codec||!delivery||!safe_asset(asset))continue;if(strcmp(delivery,"direct")||!capability_codec(cd,cap,codec,rate)){p->needs_transcode=1;continue;}if(rate>=best){best=rate;snprintf(p->id,sizeof(p->id),"%s",id?id:"default");snprintf(p->asset,sizeof(p->asset),"%s",asset);snprintf(p->codec,sizeof(p->codec),"%s",codec);p->bitrate=rate;p->direct=1;}}
 sqlite3_finalize(reps);reps=0;if(!p->found&&capability_codec(cd,cap,"unknown",0)){snprintf(p->id,sizeof(p->id),"default");snprintf(p->codec,sizeof(p->codec),"unknown");p->direct=1;}
out:if(reps)sqlite3_finalize(reps);if(s)sqlite3_finalize(s);if(cd)sqlite3_close(cd);return p->direct;}
static void emit_plan(const Plan*p,const char*lib,const char*actor){fputs("{\"schema\":\"bonfyre-playback-plan.v1\",\"library_id\":",stdout);js(lib);fputs(",\"actor_subject\":",stdout);js(actor);fputs(",\"subject_ref\":",stdout);js(p->subject);fputs(",\"media_program_ref\":",stdout);js(p->program);if(p->direct){fputs(",\"state\":\"DIRECT_PLAYABLE\",\"representation_id\":",stdout);js(p->id);fputs(",\"asset_ref\":",stdout);js(p->asset);fputs(",\"codec\":",stdout);js(p->codec);printf(",\"bitrate_kbps\":%d",p->bitrate);}else fputs(p->needs_transcode?",\"state\":\"REFUSED_TRANSCODE_REQUIRED\"":",\"state\":\"REFUSED_NO_COMPATIBLE_REPRESENTATION\"",stdout);fputs(",\"truth\":\"access_and_representation_plan_only_no_transport_or_watch_claim\"}\n",stdout);}
static int cmd_plan(sqlite3*d,int ac,char**av,int session){const char*cms=arg(ac,av,"--cms-db"),*lib=arg(ac,av,"--library"),*actor=arg(ac,av,"--actor"),*subject=arg(ac,av,"--subject"),*cap=arg(ac,av,"--capabilities");Plan p={0};sqlite3_stmt*s=0;char sid[128];if(!cms||!token(lib)||!token(actor)||!token(subject)||!cap)return 0;resolve(d,cms,lib,actor,subject,cap,&p);if(!session){emit_plan(&p,lib,actor);return p.direct;}if(!p.direct){emit_plan(&p,lib,actor);return 0;}snprintf(sid,sizeof(sid),"play:%ld:%ld:%s",(long)time(0),(long)getpid(),p.id);if(sqlite3_prepare_v2(d,"INSERT INTO media_playback_session VALUES(?1,?2,?3,?4,?5,?6,'prepared',0,?7,?7)",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,sid,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,lib,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,actor,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,4,subject,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,5,p.program,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,6,p.id,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,7,time(0));int ok=sqlite3_step(s)==SQLITE_DONE;sqlite3_finalize(s);if(ok){fputs("{\"schema\":\"bonfyre-playback-session.v1\",\"session_id\":",stdout);js(sid);fputs(",\"state\":\"prepared\",\"truth\":\"prepared_session_not_delivery_or_watched_occurrence\"}\n",stdout);}return ok;}
static int cmd_plan_request(sqlite3*d,int ac,char**av){return cmd_plan(d,ac,av,0);}
static int cmd_session_request(sqlite3*d,int ac,char**av){return cmd_plan(d,ac,av,1);}
static int cmd_progress(sqlite3*d,int ac,char**av){const char*sid=arg(ac,av,"--session"),*actor=arg(ac,av,"--actor"),*pos=arg(ac,av,"--position-ms"),*state=arg(ac,av,"--state");sqlite3_stmt*s=0;long long n=pos?strtoll(pos,0,10):-1;if(!sid||!token(actor)||n<0||!state||((strcmp(state,"playing")&&strcmp(state,"paused")&&strcmp(state,"ended"))))return 0;if(sqlite3_prepare_v2(d,"UPDATE media_playback_session SET position_ms=?1,state=?2,updated_at=?3 WHERE session_id=?4 AND actor_subject=?5",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_int64(s,1,n);sqlite3_bind_text(s,2,state,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,3,time(0));sqlite3_bind_text(s,4,sid,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,5,actor,-1,SQLITE_TRANSIENT);int ok=sqlite3_step(s)==SQLITE_DONE&&sqlite3_changes(d)==1;sqlite3_finalize(s);if(ok)printf("{\"schema\":\"bonfyre-playback-progress.v1\",\"state\":\"%s\",\"position_ms\":%lld,\"truth\":\"actor_reported_continuity_not_watch_proof\"}\n",state,n);return ok;}
static int cmd_continue(sqlite3*d,int ac,char**av){const char*actor=arg(ac,av,"--actor"),*lib=arg(ac,av,"--library");sqlite3_stmt*s=0;int first=1;if(!token(actor)||!token(lib)||!visible(d,lib,actor)||sqlite3_prepare_v2(d,"SELECT subject_ref,media_program_ref,representation_id,position_ms,state FROM media_playback_session WHERE library_id=?1 AND actor_subject=?2 AND state IN ('prepared','playing','paused') ORDER BY updated_at DESC LIMIT 48",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,lib,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,actor,-1,SQLITE_TRANSIENT);fputs("{\"schema\":\"bonfyre-media-continue.v1\",\"items\":[",stdout);while(sqlite3_step(s)==SQLITE_ROW){if(!first)putchar(',');first=0;fputs("{\"subject_ref\":",stdout);js((const char*)sqlite3_column_text(s,0));fputs(",\"media_program_ref\":",stdout);js((const char*)sqlite3_column_text(s,1));fputs(",\"representation_id\":",stdout);js((const char*)sqlite3_column_text(s,2));printf(",\"position_ms\":%lld,\"state\":",sqlite3_column_int64(s,3));js((const char*)sqlite3_column_text(s,4));putchar('}');}fputs("],\"truth\":\"actor_local_playback_continuity_only\"}\n",stdout);sqlite3_finalize(s);return 1;}
static int cmd_catalog(sqlite3*d,int ac,char**av){const char*lib=arg(ac,av,"--library"),*actor=arg(ac,av,"--actor");sqlite3_stmt*s=0;int first=1;if(!token(lib)||!token(actor)||!visible(d,lib,actor)||sqlite3_prepare_v2(d,"SELECT l.mode,l.title,l.visibility,m.subject_ref,m.media_program_ref,m.collection_ref FROM media_library l JOIN media_library_membership m ON m.library_id=l.library_id WHERE l.library_id=?1 AND m.state='active' ORDER BY m.collection_ref,m.subject_ref",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,lib,-1,SQLITE_TRANSIENT);fputs("{\"schema\":\"bonfyre-media-library-catalog.v1\",\"library_id\":",stdout);js(lib);fputs(",\"items\":[",stdout);while(sqlite3_step(s)==SQLITE_ROW){if(!first)putchar(',');first=0;fputs("{\"mode\":",stdout);js((const char*)sqlite3_column_text(s,0));fputs(",\"title\":",stdout);js((const char*)sqlite3_column_text(s,1));fputs(",\"visibility\":",stdout);js((const char*)sqlite3_column_text(s,2));fputs(",\"subject_ref\":",stdout);js((const char*)sqlite3_column_text(s,3));fputs(",\"media_program_ref\":",stdout);js((const char*)sqlite3_column_text(s,4));fputs(",\"collection_ref\":",stdout);js((const char*)sqlite3_column_text(s,5));putchar('}');}fputs("],\"truth\":\"library_memberships_reference_media_not_media_identity_or_rights\"}\n",stdout);sqlite3_finalize(s);return 1;}
/* A MediaLibrary surface is a typed human projection boundary.  It resolves
 * exact library visibility before reading representation labels, and produces
 * a Kodi-like personal grammar or Jellyfin-like communal grammar.  It does
 * not deliver bytes, create a stream lease, or turn a listed item into a
 * viewing or distribution right. */
static void surface_nav(const char *mode) {
    static const char *const personal[] = {"ContinueWatching","Movies","Shows","Music","Photos","Live","Playlists","Favorites","Sources"};
    static const char *const community[] = {"Home","Live","Videos","Series","Collections","Playlists","Community","Events","About"};
    const char *const *items = !strcmp(mode,"personal") ? personal : community;
    size_t count = !strcmp(mode,"personal") ? sizeof(personal)/sizeof(*personal) : sizeof(community)/sizeof(*community);
    fputs("[",stdout); for(size_t i=0;i<count;i++){if(i)putchar(',');js(items[i]);} fputs("]",stdout);
}
static int surface_shelf(const char *kind) {
    if(!kind)return 5;
    if(!strcmp(kind,"movie")||!strcmp(kind,"film"))return 0;
    if(!strcmp(kind,"show")||!strcmp(kind,"series")||!strcmp(kind,"episode"))return 1;
    if(!strcmp(kind,"music")||!strcmp(kind,"audio")||!strcmp(kind,"podcast"))return 2;
    if(!strcmp(kind,"photo")||!strcmp(kind,"image")||!strcmp(kind,"picture"))return 3;
    if(!strcmp(kind,"live"))return 4;
    return 5;
}
static int cmd_surface(sqlite3*d,int ac,char**av){
    const char *lib=arg(ac,av,"--library"),*actor=arg(ac,av,"--actor"),*cms=arg(ac,av,"--cms-db");
    sqlite3_stmt *library=0,*members=0,*program=0; sqlite3 *cd=0; int first=1,shelves[6]={0};
    const char *mode=0,*title=0,*visibility=0;
    if(!token(lib)||!token(actor)||!cms||!visible(d,lib,actor)||sqlite3_open_v2(cms,&cd,SQLITE_OPEN_READONLY,0)!=SQLITE_OK)return 0;
    if(sqlite3_prepare_v2(d,"SELECT mode,title,visibility FROM media_library WHERE library_id=?1 AND state='active'",-1,&library,0)!=SQLITE_OK)goto fail;
    sqlite3_bind_text(library,1,lib,-1,SQLITE_TRANSIENT);
    if(sqlite3_step(library)!=SQLITE_ROW)goto fail;
    mode=(const char*)sqlite3_column_text(library,0); title=(const char*)sqlite3_column_text(library,1); visibility=(const char*)sqlite3_column_text(library,2);
    if(!mode||!title||!visibility)goto fail;
    fputs("{\"schema\":\"bonfyre-media-library-surface.v1\",\"library_id\":",stdout);js(lib);
    fputs(",\"grammar\":",stdout);js(!strcmp(mode,"personal")?"personal_media_habitat":"community_media_channel");
    fputs(",\"mode\":",stdout);js(mode);fputs(",\"title\":",stdout);js(title);fputs(",\"visibility\":",stdout);js(visibility);
    fputs(",\"navigation\":",stdout);surface_nav(mode);fputs(",\"items\":[",stdout);
    if(sqlite3_prepare_v2(d,"SELECT subject_ref,media_program_ref,collection_ref FROM media_library_membership WHERE library_id=?1 AND state='active' ORDER BY collection_ref,subject_ref LIMIT 50",-1,&members,0)!=SQLITE_OK)goto fail;
    if(sqlite3_prepare_v2(cd,"SELECT COALESCE(media_kind,'unresolved'),COALESCE(publication_state,'unresolved'),COALESCE(status,'unresolved') FROM media_program WHERE program_id=?1 ORDER BY id DESC LIMIT 1",-1,&program,0)!=SQLITE_OK)goto fail;
    sqlite3_bind_text(members,1,lib,-1,SQLITE_TRANSIENT);
    while(sqlite3_step(members)==SQLITE_ROW){
        const char *subject=(const char*)sqlite3_column_text(members,0),*ref=(const char*)sqlite3_column_text(members,1),*collection=(const char*)sqlite3_column_text(members,2);
        char kind[64]="unresolved",publication[64]="unresolved",status[64]="unresolved";
        sqlite3_bind_text(program,1,ref?ref:"",-1,SQLITE_TRANSIENT);
        if(sqlite3_step(program)==SQLITE_ROW){snprintf(kind,sizeof(kind),"%s",sqlite3_column_text(program,0)?(const char*)sqlite3_column_text(program,0):"unresolved");snprintf(publication,sizeof(publication),"%s",sqlite3_column_text(program,1)?(const char*)sqlite3_column_text(program,1):"unresolved");snprintf(status,sizeof(status),"%s",sqlite3_column_text(program,2)?(const char*)sqlite3_column_text(program,2):"unresolved");}
        sqlite3_reset(program);sqlite3_clear_bindings(program);
        shelves[surface_shelf(kind)]++;
        if(!first)putchar(',');first=0;fputs("{\"subject_ref\":",stdout);js(subject);fputs(",\"media_program_ref\":",stdout);js(ref);fputs(",\"collection_ref\":",stdout);js(collection);fputs(",\"media_kind\":",stdout);js(kind);fputs(",\"representation_publication\":",stdout);js(publication);fputs(",\"representation_status\":",stdout);js(status);putchar('}');
    }
    fputs("],\"shelves\":[",stdout);
    {static const char *const ids[]={"movies","shows","music","photos","live","videos"};int shelf_first=1;for(size_t i=0;i<sizeof(ids)/sizeof(*ids);i++)if(shelves[i]){if(!shelf_first)putchar(',');shelf_first=0;fputs("{\"id\":",stdout);js(ids[i]);printf(",\"items\":%d}",shelves[i]);}}
    fputs("],\"truth\":\"surface_projection_of_accessible_library_only_no_transport_delivery_or_watch_claim\"}\n",stdout);
    sqlite3_finalize(library);sqlite3_finalize(members);sqlite3_finalize(program);sqlite3_close(cd);return 1;
fail:
    sqlite3_finalize(library);sqlite3_finalize(members);sqlite3_finalize(program);if(cd)sqlite3_close(cd);return 0;
}
static int cmd_ads(sqlite3*d){
    sqlite3_stmt*s=0; int n=0;
    if(sqlite3_prepare_v2(d,"SELECT l.library_id,l.mode,l.visibility,m.subject_ref,m.media_program_ref FROM media_library l JOIN media_library_membership m ON m.library_id=l.library_id WHERE l.state='active' AND m.state='active' ORDER BY l.library_id,m.subject_ref",-1,&s,0)!=SQLITE_OK)return 0;
    while(sqlite3_step(s)==SQLITE_ROW){
        const char *lib=(const char*)sqlite3_column_text(s,0), *mode=(const char*)sqlite3_column_text(s,1), *vis=(const char*)sqlite3_column_text(s,2), *sub=(const char*)sqlite3_column_text(s,3), *program=(const char*)sqlite3_column_text(s,4);
        char subject_atom[256], library_atom[192];
        if(!lib||!mode||!vis||!sub||!program||!term_atom(sub,subject_atom,sizeof(subject_atom))||!term_atom(lib,library_atom,sizeof(library_atom))){sqlite3_finalize(s);return 0;}
        fputs("{\"identity\":",stdout); printf("\"media:library:%s:%s\"",lib,program);
        fputs(",\"candidate_kind\":\"media_library\",\"owner_ref\":",stdout); printf("\"MediaLibrary:%s\"",lib);
        fputs(",\"exact_verifier\":\"MediaLibrary:access\",\"lowerer_ref\":\"MediaLibraryCompiler:surface\",\"validity_frontier\":",stdout); printf("\"MediaLibrary:%s\"",lib);
        fputs(",\"terms\":[\"subject:",stdout); fputs(subject_atom,stdout);
        fputs("\",\"library:",stdout); fputs(library_atom,stdout);
        fputs("\",\"material:",stdout); fputs(mode,stdout);
        fputs("\",\"operation:playback\",\"representation:media-program\",\"audience:",stdout); fputs(vis,stdout);
        fputs("\"],\"dependencies\":[",stdout); printf("\"MediaLibrary:%s\",\"CMS:media_program:%s\"]}\n",lib,program);
        n++;
    }
    sqlite3_finalize(s);
    fprintf(stderr,"{\"schema\":\"bonfyre-media-library-advertisements.v1\",\"emitted\":%d,\"truth\":\"forwarding_descriptors_only\"}\n",n);
    return n>0;
}
static void use(void){fputs("bonfyre-media-library library-put --db FILE --id ID --mode personal|community --owner SUBJECT --actor SUBJECT --title TITLE --visibility private|community|public\n       bonfyre-media-library access-put --db FILE --library ID --actor SUBJECT --role viewer|curator|admin --state active|revoked --by SUBJECT\n       bonfyre-media-library bind --db FILE --library ID --subject SUBJECT --program PROGRAM [--collection ID] --state active|removed --by SUBJECT\n       bonfyre-media-library catalog|surface|playback-plan|session-open|progress|continue ... --actor SUBJECT  # internal owner boundary\n       bonfyre-media-library authenticated-catalog|authenticated-surface|authenticated-playback-plan|authenticated-session-open|authenticated-progress|authenticated-continue ... --auth-db FILE --auth-token TOKEN [--actor EXPECTED]\n       bonfyre-media-library emit-advertisements --db FILE\n",stderr);}
int main(int ac,char**av){const char*path=arg(ac,av,"--db");sqlite3*d=0;int ok=0;if(ac<2||!path){use();return 2;}if(!open_db(path,&d))return 1;if(!strcmp(av[1],"library-put"))ok=cmd_library(d,ac,av);else if(!strcmp(av[1],"access-put"))ok=cmd_access(d,ac,av);else if(!strcmp(av[1],"bind"))ok=cmd_bind(d,ac,av);else if(!strcmp(av[1],"catalog"))ok=cmd_catalog(d,ac,av);else if(!strcmp(av[1],"surface"))ok=cmd_surface(d,ac,av);else if(!strcmp(av[1],"playback-plan"))ok=cmd_plan_request(d,ac,av);else if(!strcmp(av[1],"session-open"))ok=cmd_session_request(d,ac,av);else if(!strcmp(av[1],"progress"))ok=cmd_progress(d,ac,av);else if(!strcmp(av[1],"continue"))ok=cmd_continue(d,ac,av);else if(!strcmp(av[1],"authenticated-catalog"))ok=authenticated_call(d,ac,av,cmd_catalog);else if(!strcmp(av[1],"authenticated-surface"))ok=authenticated_call(d,ac,av,cmd_surface);else if(!strcmp(av[1],"authenticated-playback-plan"))ok=authenticated_call(d,ac,av,cmd_plan_request);else if(!strcmp(av[1],"authenticated-session-open"))ok=authenticated_call(d,ac,av,cmd_session_request);else if(!strcmp(av[1],"authenticated-progress"))ok=authenticated_call(d,ac,av,cmd_progress);else if(!strcmp(av[1],"authenticated-continue"))ok=authenticated_call(d,ac,av,cmd_continue);else if(!strcmp(av[1],"emit-advertisements"))ok=cmd_ads(d);else{use();sqlite3_close(d);return 2;}sqlite3_close(d);return ok?0:1;}
